<?php
namespace Tests\Feature; use App\Models\{Booking,Property,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class SprintsNineToTwelveTest extends TestCase {use RefreshDatabase; public function test_customer_cannot_read_another_customers_service_requests():void{$a=User::factory()->create(['account_type'=>'customer']);$b=User::factory()->create(['account_type'=>'customer']);$this->actingAs($a)->get('/account/service-requests/999')->assertNotFound();} public function test_document_routes_require_authentication():void{$this->get('/account/bookings/ABC/documents/invoice')->assertRedirect('/login');} public function test_public_verification_does_not_expose_stay_dates():void{$u=User::factory()->create();$p=Property::factory()->create();$b=Booking::factory()->create(['user_id'=>$u->id,'property_id'=>$p->id,'reference'=>'AZR-PRIVATE','status'=>'confirmed']);$r=$this->getJson('/verify-booking?reference=AZR-PRIVATE');$r->assertOk()->assertJsonPath('booking.reference','AZR-PRIVATE')->assertJsonMissingPath('booking.check_in')->assertJsonMissingPath('booking.check_out');}}
